#include <iostream>
using namespace std;

int row, col;
char maze[100][100];       // 迷宫，'0'通路 '#'墙
int visited[100][100];     // 访问标记
int startX, startY;        // 起点
int endX, endY;            // 终点

// 手写队列（最原始）
int qx[10000];             // 队列存 x
int qy[10000];             // 队列存 y
int qstep[10000];          // 队列存步数
int head, tail;            // 队头队尾

// 上右下左 四个方向的偏移
int dx[4] = {-1, 0, 1, 0};
int dy[4] = {0, 1, 0, -1};

// 判断能不能站在 (nx, ny)
int canGo(int nx, int ny) {
    if (nx < 0 || nx >= row) return 0;      // 出界
    if (ny < 0 || ny >= col) return 0;      // 出界
    if (maze[nx][ny] == '#') return 0;      // 是墙
    if (visited[nx][ny] == 1) return 0;     // 走过了
    return 1;
}

int bfs() {
    // 起点入队
    head = 0;
    tail = 0;
    qx[tail] = startX;
    qy[tail] = startY;
    qstep[tail] = 0;
    tail = tail + 1;
    visited[startX][startY] = 1;

    // 队列非空就继续
    while (head < tail) {
        // 取出队头
        int cx = qx[head];
        int cy = qy[head];
        int cstep = qstep[head];
        head = head + 1;

        // 到终点了，第一次到达就是最短，直接返回
        if (cx == endX && cy == endY) {
            return
cstep;
        }

        // 四个方向都试一遍
        for (int i = 0; i < 4; i++) {
            int nx = cx + dx[i];
            int ny = cy + dy[i];

            if (canGo(nx, ny) == 1) {
                visited[nx][ny] = 1;           // 入队前标记
                qx[tail] = nx;                 // 新点入队
                qy[tail] = ny;
                qstep[tail] = cstep + 1;
                tail = tail + 1;
            }
        }
    }

    return -1;   // 走不到终点
}

int main() {
    cin >> row >> col;

    // 读迷宫
    for (int i = 0; i < row; i++) {
        for (int j = 0; j < col; j++) {
            cin >> maze[i][j];
        }
    }

    // 找起点和终点（假设 'S' 起点，'E' 终点）
    for (int i = 0; i < row; i++) {
        for (int j = 0; j < col; j++) {
            if (maze[i][j] == 'S') {
                startX = i;
startY = j;
            }
            if (maze[i][j] == 'E') {
                endX = i; endY = j;
            }
        }
    }

    int ans = bfs();
    if (ans == -1) {
        cout << "走不到终点" << endl;
    } else {
        cout << "最短步数: " << ans << endl;
    }

    return 0;
}

#include <iostream>
#include <queue>
using namespace std;

const int MAXN = 105;
int n, m;
int grid[MAXN][MAXN];   // 地图：0 空地，1 墙
int dist[MAXN][MAXN];   // 从起点到每个格子的最短步数，0 表示还没走到
int dx[4] = {-1, 1, 0, 0};  // 上、下、左、右
int dy[4] = {0, 0, -1, 1};

int bfs() {
    queue<pair<int, int>> q;
    q.push({0, 0});     // 起点入队
    dist[0][0] = 1;     // 起点算第 1 格

    while (!q.empty()) {
        int x = q.front().first;
        int y = q.front().second;
        q.pop();

        // 第一次弹出终点时，一定是最短路径（BFS 按层扩展）
        if (x == n - 1 && y == m - 1) return dist[x][y];

        // 尝试朝四个方向走
        for (int i = 0; i < 4; i++) {
            int nx = x + dx[i];
            int ny = y + dy[i];

            // 出界 / 撞墙 / 已经走过 -> 跳过
            if (nx < 0 || nx >= n || ny < 0 || ny >= m) continue;
            if (grid[nx][ny] == 1) continue;
            if (dist[nx][ny] != 0) continue;

            dist[nx][ny] = dist[x][y] + 1;  // 步数 = 当前格步数 + 1
            q.push({nx, ny});
        }
    }
    return -1;  // 走不到终点
}

int main() {
    cin >> n >> m;
    for (int i = 0; i < n; i++)
        for (int j = 0; j < m; j++)
            cin >> grid[i][j];

    cout << bfs() << endl;
    return 0;
}

